arguments.command:
bundle exec ruby -r stackprof -e '
data = Marshal.load(File.binread("tmp/test_prof/stack-prof-report-wall-raw-total.dump"))
frames = data[:frames]

# Print top frames matching app/, spec/, or key gems
puts "=== Top frames in app/ ==="
frames.select { |_, f| f[:file].to_s.include?("/app/") }
  .sort_by { |_, f| -f[:total_samples] }
  .first(30)
  .each { |_, f| printf "%7d (%5.1f%%) %7d self  %s (%s:%d)\n", f[:total_samples], f[:total_samples]*100.0/data[:samples], f[:samples], f[:name], f[:file].sub(%r{.*/app/}, "app/"), f[:line].to_i }

puts "\n=== Top frames in spec/ ==="
frames.select { |_, f| f[:file].to_s.include?("/spec/") }
  .sort_by { |_, f| -f[:total_samples] }
  .first(30)
  .each { |_, f| printf "%7d (%5.1f%%) %7d self  %s (%s:%d)\n", f[:total_samples], f[:total_samples]*100.0/data[:samples], f[:samples], f[:name], f[:file].sub(%r{.*/spec/}, "spec/"), f[:line].to_i }
'

grep -rn "include_context 'with API authentication'" spec/requests/ | wc -l && bundle exec ruby -e '
require "./spec/rails_helper"
# Quick monkeypatch to count sidekiq inline worker classes during a small run? No, let us inspect stackprof dump for Worker#perform!
' && bundle exec ruby -r stackprof -e '
data = Marshal.load(File.binread("tmp/test_prof/stack-prof-report-wall-raw-total.dump"))
data[:frames].select { |_, f| f[:name].to_s.include?("Worker#perform") || f[:file].to_s.include?("app/workers/") }
  .sort_by { |_, f| -f[:total_samples] }
  .first(25)
  .each { |_, f| printf "%7d (%5.1f%%)  %s (%s:%d)\n", f[:total_samples], f[:total_samples]*100.0/data[:samples], f[:name], f[:file].sub(%r{.*/app/}, "app/"), f[:line].to_i }
'

bundle exec ruby -r stackprof -e '
data = Marshal.load(File.binread("tmp/test_prof/stack-prof-report-wall-raw-total.dump"))
data[:frames].select { |_, f| f[:name].to_s.include?("Worker#perform") || f[:file].to_s.include?("app/workers/") }
  .sort_by { |_, f| -f[:total_samples] }
  .first(30)
  .each { |_, f| printf "%7d (%5.1f%%)  %s (%s:%d)\n", f[:total_samples], f[:total_samples]*100.0/data[:samples], f[:name], f[:file].sub(%r{.*/app/}, "app/"), f[:line].to_i }
'

bundle exec rspec spec/requests --format json --out tmp/requests_baseline.json --format progress && ruby -r json -e '
data = JSON.parse(File.read("tmp/requests_baseline.json"))
by_file = data["examples"].group_by { |e| e["file_path"] }
puts "Total examples: #{data["examples"].size}, duration: #{data["summary"]["duration"].round(2)}s"
puts "\nTop 40 slowest files:"
by_file.map { |f, exs| [f, exs.sum { |e| e["run_time"] }, exs.size] }
  .sort_by { |_, t, _| -t }
  .first(40)
  .each { |f, t, n| printf "%6.2fs (%3d ex, %5.3fs/ex)  %s\n", t, n, t/n, f }
'

grep -rn "include_context 'with API authentication'" spec/requests/ && echo "--- total time check ---" && ruby -r json -e '
data = JSON.parse(File.read("tmp/requests_baseline.json"))
by_file = data["examples"].group_by { |e| e["file_path"] }
top10 = by_file.map { |f, exs| [f, exs.sum { |e| e["run_time"] }] }.sort_by { |_, t| -t }.first(10).sum { |_, t| t }
top20 = by_file.map { |f, exs| [f, exs.sum { |e| e["run_time"] }] }.sort_by { |_, t| -t }.first(20).sum { |_, t| t }
puts "Total: #{data["summary"]["duration"].round(2)}s, Top 10 files: #{top10.round(2)}s, Top 20 files: #{top20.round(2)}s"
'

